<script setup>
import { onMounted, ref, watch } from 'vue'
import { ArrowLeft, Search, ShoppingCart, X } from 'lucide-vue-next'
import { useRoute, useRouter } from 'vue-router'
import { searchProducts } from '../services/searchService'
import { useCartStore } from '../stores/cart'

const route = useRoute(); const router = useRouter(); const cart = useCartStore(); const query = ref(String(route.query.buscar || '')); const category = ref(String(route.query.categoria || '')); const products = ref([]); const loading = ref(false); const error = ref('')
async function load() { const term = query.value.trim(); const categoryTerm = category.value.trim(); if (!term && !categoryTerm) { products.value = []; return }; loading.value = true; error.value = ''; try { products.value = await searchProducts(term, categoryTerm) } catch (e) { error.value = e.message || 'No se pudo realizar la búsqueda.' } finally { loading.value = false } }
function submit() { const term = query.value.trim(); if (term) router.replace({ name: 'search', query: { buscar: term } }); else if (category.value) router.replace({ name: 'search', query: { categoria: category.value } }); else products.value = [] }
function openProduct(product) { router.push({ name: 'product-detail', params: { restaurantId: product.restaurante_id, productId: product.id } }) }
watch(() => [route.query.buscar, route.query.categoria], ([value, categoryValue]) => { query.value = String(value || ''); category.value = String(categoryValue || ''); load() }); onMounted(load)
</script>
<template>
<main class="catalog-page search-results-page"><header class="catalog-header"><div class="catalog-topbar"><button class="icon-button" aria-label="Regresar" @click="router.push('/')"><ArrowLeft :size="26" /></button><form class="catalog-search" @submit.prevent="submit"><Search :size="20" /><input v-model="query" placeholder="Locales, platos y productos" aria-label="Buscar productos" /><button v-if="query" type="button" class="search-clear" @click="query = ''; submit()"><X :size="16" /></button></form><button class="icon-button cart-link" aria-label="Carrito" @click="router.push('/carrito')"><ShoppingCart :size="25" /><b v-if="cart.count" class="cart-badge">{{ cart.count }}</b></button></div></header><section class="catalog-content"><div class="catalog-heading"><h1>{{ category ? `Productos de ${category}` : `${products.length} ${products.length === 1 ? 'producto encontrado' : 'productos encontrados'}` }}</h1></div><div v-if="loading" class="catalog-state">Buscando productos…</div><p v-else-if="error" class="catalog-state catalog-state--error">{{ error }}</p><p v-else-if="!products.length" class="catalog-state">No encontramos productos{{ category ? ` en la categoría ${category}` : ` similares a “${query}”` }}.</p><div v-else class="search-product-list"><article v-for="product in products" :key="`${product.restaurante_id}-${product.id}`" class="search-product-card" @click="openProduct(product)"><img :src="product.image" :alt="product.nombre" /><div><h2>{{ product.nombre }}</h2><p>{{ product.descripcion || 'Producto disponible' }}</p><small class="search-product-store"><img :src="product.restaurantImage" :alt="`Logotipo de ${product.restaurantes?.nombre}`" />{{ product.restaurantes?.nombre }}</small><strong>${{ Number(product.precio).toFixed(2) }}</strong></div></article></div></section></main>
</template>
